INSERT INTO figures (id, name, name_alt, years, era, region, role, tags, bio, relation, story, image, mds, dlabels, dkinds, note, relations, rel_notes) VALUES
  (41, '陀思妥耶夫斯基', 'Fyodor Dostoevsky', '1821—1881', '19世纪', '俄国', '小说家', ARRAY['文学家', '俄国', '小说'], '俄国小说家，存在主义思想的先驱。《罪与罚》《卡拉马佐夫兄弟》以深邃的心理与信仰之问震撼世界。', '牌搭子', '', 'assets/figures/dostoevsky.jpg', ARRAY['11-11', '01-01'], ARRAY['诞辰 · 1821年11月11日', '《罪与罚》出版 · 1866年1月1日'], ARRAY['birth', 'event'], '他赌到身无分文，只能靠写作还债；你陪他熬过那些债主上门的日子。', ARRAY['牌搭子', '西伯利亚难友'], ARRAY['他赌到身无分文，只能靠写作还债；你陪他熬过那些债主上门的日子。', '他被流放西伯利亚服苦役，同棚里替他挡过鞭子的是你。']),
  (42, '列夫·托尔斯泰', 'Leo Tolstoy', '1828—1910', '19—20世纪', '俄国', '小说家', ARRAY['文学家', '俄国', '小说'], '俄国小说家，《战争与和平》《安娜·卡列尼娜》的作者。他晚年寻求简朴与信仰，思想影响深远。', '邻居', '', 'assets/figures/tolstoy.jpg', ARRAY['09-09', '01-01'], ARRAY['诞辰 · 1828年9月9日', '《战争与和平》完成 · 1869年'], ARRAY['birth', 'event'], '七十岁那年他离家出走，走了几百公里死在火车站；邻居是最后一批见到他的人。', ARRAY['邻居', '庄园先生'], ARRAY['七十岁那年他离家出走，走了几百公里死在火车站；邻居是最后一批见到他的人。', '他在亚斯纳亚庄园办学教书，替他管学堂、哄孩子的邻居是你。']),
  (43, '艾米莉·狄金森', 'Emily Dickinson', '1830—1886', '19世纪', '美国', '诗人', ARRAY['文学家', '美国', '诗歌'], '美国诗人，生前几乎未发表。她留下近一千八百首意象奇崛、凝练深刻的诗，死后才被公认为大师。', '笔友', '', 'assets/figures/dickinson.jpg', ARRAY['12-10', '11-01'], ARRAY['诞辰 · 1830年12月10日', '诗集出版 · 1890年11月'], ARRAY['birth', 'event'], '她一生只发表过十来首诗，其余的一千八百首缝在饼干盒里寄给你。', ARRAY['笔友', '花园邻居'], ARRAY['她一生只发表过十来首诗，其余的一千八百首缝在饼干盒里寄给你。', '她几乎不出门，隔篱递诗稿、送鲜花的那个园邻是你。']),
  (44, '弗吉尼亚·伍尔夫', 'Virginia Woollf', '1882—1941', '19—20世纪', '英国', '小说家', ARRAY['文学家', '英国', '现代派'], '英国小说家，意识流文学的代表。《达洛维夫人》《到灯塔去》以内在时间重构叙事，是现代主义的标志。', '邻居', '', 'assets/figures/woolf.jpg', ARRAY['01-25', '05-14'], ARRAY['诞辰 · 1882年1月25日', '《达洛维夫人》出版 · 1925年5月14日'], ARRAY['birth', 'event'], '她写句子像水流，邻居隔着墙只听得见笔尖的声音。', ARRAY['邻居', '刊物编辑'], ARRAY['她写句子像水流，邻居隔着墙只听得见笔尖的声音。', '她和丈夫办霍加斯出版社，经手她书稿的编辑是你。']),
  (45, '欧内斯特·海明威', 'Ernest Hemingway', '1899—1961', '20世纪', '美国', '小说家', ARRAY['文学家', '美国', '小说'], '美国小说家，以简洁硬朗的文风著称。他亲历两次世界大战，作品《老人与海》为他赢得诺贝尔文学奖。', '球友', '', 'assets/figures/hemingway.jpg', ARRAY['07-21', '09-01'], ARRAY['诞辰 · 1899年7月21日', '《老人与海》出版 · 1952年9月1日'], ARRAY['birth', 'event'], '他站着写，鞋底磨穿；最好的几段是在钓上大鱼的那天写下的。', ARRAY['球友', '报社交稿人'], ARRAY['他站着写，鞋底磨穿；最好的几段是在钓上大鱼的那天写下的。', '他在《星报》当记者，骑着车把稿子送进编辑部的同伴是你。']),
  (46, '卡利古拉', 'Caligula', '12—41', '古罗马', '罗马', '皇帝', ARRAY['帝王', '罗马', '暴君'], '罗马皇帝，朱里亚·克劳狄王朝第三位君主。他早年受军爱戴，后期以荒诞与残暴著称，最终被近卫军刺杀。', '军营同袍', '', 'assets/figures/caligula.jpg', ARRAY['08-31', '03-16'], ARRAY['诞辰 · 12年8月31日', '即位 · 37年3月16日'], ARRAY['birth', 'throne'], '他爱和自己的士兵一起行军，你也是队伍里的一个。', ARRAY['军营同袍', '马厩小厮'], ARRAY['他爱和自己的士兵一起行军，你也是队伍里的一个。', '他最爱的那匹马.incitatus 由你喂料，他甚至在饭桌上替它留座。']),
  (47, '伊丽莎白·巴托里', 'Elizabeth Báthory', '1560—1614', '16—17世纪', '匈牙利', '贵族', ARRAY['贵族', '匈牙利', '历史'], '匈牙利贵族女性，欧洲历史上最著名的女贵族之一。她因涉嫌残酷虐待女仆而闻名后世，形象长久被传说与戏剧化。', '邻居', '', 'assets/figures/bathory.jpg', ARRAY['08-14', '12-29'], ARRAY['诞辰 · 1560年8月14日', '受审 · 1610年12月29日'], ARRAY['birth', 'event'], '城堡里发生了什么，邻居都不清楚；他们只记得那扇不该打开的门。', ARRAY['邻居', '城堡女仆'], ARRAY['城堡里发生了什么，邻居都不清楚；他们只记得那扇不该打开的门。', '你在城堡里替她管过一阵女仆，后来是你第一个报了官。']),
  (48, '马克西米连·罗伯斯庇尔', 'Maximilien Robespierre', '1758—1794', '18世纪', '法国', '革命家', ARRAY['政治家', '法国', '革命'], '法国大革命的核心人物，雅各宾派领袖。他推动共和、主导恐怖统治，最终在热月政变中被送上断头台。', '辩护律师', '', 'assets/figures/robespierre.jpg', ARRAY['05-06', '09-21'], ARRAY['诞辰 · 1758年5月6日', '国民公会成立 · 1792年9月21日'], ARRAY['birth', 'event'], '你替断头台辩护过，最后那台机器送走的是他自己。', ARRAY['辩护律师', '雅各宾书记'], ARRAY['你替断头台辩护过，最后那台机器送走的是他自己。', '他在雅各宾俱乐部口若悬河，替他记发言、收发传单的是你。']),
  (49, '切萨雷·波吉亚', 'Cesare Borgia', '1475—1507', '文艺复兴', '意大利', '枢机 · 统帅', ARRAY['政治家', '意大利', '文艺复兴'], '意大利文艺复兴时期的枢机主教与军事领袖，教皇亚历山大六世之子。他以权谋统一罗马涅，是马基雅维利笔下的理想君主原型。', '合租室友', '', 'assets/figures/borgia.jpg', ARRAY['09-13', '07-31'], ARRAY['诞辰 · 1475年9月13日', '当选枢机 · 1500年7月31日'], ARRAY['birth', 'event'], '他解决政敌的方式是毒药，而你就睡在隔壁。', ARRAY['合租室友', '枢机随从'], ARRAY['他解决政敌的方式是毒药，而你就睡在隔壁。', '他出入教廷的日程你替他打理，信使往来都经你的手。']),
  (50, '约瑟夫·梅里克', 'Joseph Merrick', '1862—1890', '19世纪', '英国', '演出者', ARRAY['历史', '英国', '医学'], '英国人，因严重的身体畸形而在马戏团展出，史称象人。后得到医生收容与照料，其遭遇唤起了对尊严的关注。', '医生助理', '', 'assets/figures/merrick.jpg', ARRAY['08-05', '12-30'], ARRAY['诞辰 · 1862年8月5日', '离开马戏团 · 1885年12月30日'], ARRAY['birth', 'event'], '医生收留了他，也把他写进了自己的书里。', ARRAY['医生助理', '马戏售票'], ARRAY['医生收留了他，也把他写进了自己的书里。', '他在马戏团被围观的年代，替他守售票亭、挡开起哄的人是你的。'])
